// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. This is RWF-016's callee, unchanged -- what RWF-017 is about is
// the POSITION the call is written in, below.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A same-name decoy nested inside a function that is never called at
// module scope. Real JS lexical scoping never resolves the module-scope
// call below to this one, and the deferred body never runs at load time
// either -- so it changes no answer, and the oracle does not depend on it.
function configure() {
  function bail() {
    return "configured";
  }
  return bail();
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-017 shape. The call is NOT a bare `bail();` expression
  // statement -- it is the INITIALIZER of a variable declaration, which
  // JavaScript evaluates as part of executing the declaration. The call
  // therefore necessarily happens, never returns, the declaration never
  // completes, `result` is never bound, and module evaluation on this
  // branch ends here. RWF-016 recognised this callee but not this
  // position.
  const result = bail();
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's own return/throw
// cutoff finds nothing here to object to either, since there is no bare
// `return`/`throw` at module scope at all.
module.exports = slowPath;
